<script setup lang="ts">
const {t}=useI18n(),warehouse=useWarehouseStore(),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const ready=ref(false)
const allowed=(...permissions:string[])=>ready.value&&staff.hasPermission(...permissions)
const loading=ref(true),error=ref(''),counts=ref<Record<string,number>>({}),tasks=ref<any[]>([]),receipts=ref<any[]>([]),pending=ref<any>(null),low=ref<number|null>(null)
const warehouseRows=ref<any[]>([])
const daily=ref<any>(null)
const schedule=ref<any>(null)
const scheduledDays=computed(()=>(schedule.value?.items||[]).filter((day:any)=>day.asn||day.cyclecount||day.pickup))
const expiry=ref<any>(null)
const outbound=['pending','in_progress','picked','packed']
const inbound=['pending','received']
const workModules=[{kind:'adjustment',status:'pending',prefix:'ADJ'},{kind:'cyclecount',status:'in_progress',prefix:'CC'},{kind:'sorting',status:'pending',prefix:'SORT'},{kind:'picking',status:'pending',prefix:'PICK'},{kind:'packing',status:'pending',prefix:'PACK'},{kind:'delivery',status:'pending',prefix:'DEL'}]
const taskWarehouseId=(task:any)=>task.warehouse_id||task.asn?.warehouse_id||task.dn?.warehouse_id||warehouse.currentWarehouse?.id
const taskWarehouseName=(task:any)=>task.warehouse?.name||warehouse.warehouses.find(row=>row.id===taskWarehouseId(task))?.name||''
let generation=0
const load=async()=>{
 if(!ready.value)return
 const seq=++generation;loading.value=true;error.value='';counts.value={};tasks.value=[];receipts.value=[];pending.value=null;low.value=null;expiry.value=null;schedule.value=null;daily.value=null;warehouseRows.value=[]
 const headers=warehouseHeaders(warehouse.currentWarehouse?.id),params={warehouse_id:warehouse.currentWarehouse?.id,is_active:true}
 const request=(path:string,extra:Record<string,any>={})=>httpRequest<any>('/api/warehouse/'+path,{params:{...params,...extra},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}})
 const jobs:Promise<any>[]=[]
 for(const kind of ['dn','asn'])if(allowed(kind+'_read'))for(const status of kind==='dn'?outbound:inbound)jobs.push(request(kind+'/',{status,per_page:kind==='asn'?3:1}).then(result=>{if(seq!==generation||!result)return;counts.value[kind+'-'+status]=result.total;if(kind==='asn')receipts.value.push(...result.items)}))
 for(const module of workModules)if(allowed((module.kind==='cyclecount'?'cycle_count':module.kind)+'_read'))jobs.push(request(module.kind+'/',{status:module.status,per_page:3}).then(result=>{if(seq===generation&&result)tasks.value.push(...result.items.map((row:any)=>({...row,kind:module.kind,prefix:module.prefix})))}))
 if(allowed('inventory_read','putaway_read','putaway_edit'))jobs.push(request('inventory/pending-putaway/summary').then(value=>{if(seq===generation)pending.value=value}))
 if(allowed('inventory_read'))jobs.push(request('inventory/',{below_low_threshold:true,per_page:1}).then(value=>{if(seq===generation)low.value=value?.total??null}))
 if(allowed('inventory_read')&&warehouse.currentWarehouse?.id)jobs.push(request('inventory/expiry',{per_page:1}).then(value=>{if(seq===generation)expiry.value=value}))
 if(warehouse.currentWarehouse?.id&&allowed('asn_read','cycle_count_read','dn_read','packing_read','delivery_read'))jobs.push(request('warehouse/'+warehouse.currentWarehouse.id+'/schedule').then(value=>{if(seq===generation)schedule.value=value}))
 if(warehouse.currentWarehouse?.id&&allowed('dn_read','inventory_read','putaway_read'))jobs.push(request('warehouse/'+warehouse.currentWarehouse.id+'/daily').then(value=>{if(seq===generation)daily.value=value?{...value,dispatch:allowed('dn_read')?value.dispatch:undefined,sent_today:allowed('dn_read')?value.sent_today:undefined,signed_today:allowed('dn_read')?value.signed_today:undefined,putaway_today:allowed('inventory_read','putaway_read')?value.putaway_today:undefined}:null}))
 if(!warehouse.currentWarehouse&&allowed('warehouse_read'))jobs.push((async()=>{
  const rows=[...warehouse.warehouses]
  for(let offset=0;offset<rows.length;offset+=4){if(seq!==generation)return;await Promise.all(rows.slice(offset,offset+4).map(async row=>{const result=await httpRequest<any>('/api/warehouse/warehouse/'+row.id+'/overview',{headers:warehouseHeaders(row.id),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation)warehouseRows.value.push({warehouse:row,data:result})}))}
  if(seq===generation)warehouseRows.value.sort((a,b)=>a.warehouse.name.localeCompare(b.warehouse.name))
 })())
 await Promise.all(jobs);if(seq===generation){tasks.value.sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));loading.value=false}
}
const initialize=async()=>{const seq=++generation;ready.value=false;loading.value=true;error.value='';counts.value={};tasks.value=[];receipts.value=[];pending.value=null;low.value=null;expiry.value=null;schedule.value=null;daily.value=null;warehouseRows.value=[];const current=await staff.getCurrentStaffInfo();if(seq!==generation)return;if(!current){error.value=t('common.validation.company-required');loading.value=false;return}await warehouse.fetchWarehouses();if(seq!==generation)return;ready.value=true;await load()}
watch(()=>warehouse.currentWarehouse?.id,load);onMounted(initialize);onBeforeUnmount(()=>generation++)
useHead({title:()=>t('dashboard-design.title')})
</script>
<template><div class="w-work-home w-scope"><header><div><p>{{warehouse.currentWarehouse?.name||t('common.all-warehouse')}} · {{t('dashboard-design.scope')}}</p><h1>{{t('dashboard-design.title')}}</h1></div><div class="actions"><WButton v-if="allowed('asn_edit')" to="/asn/add">{{t('asn.operations.add')}}</WButton><WButton v-if="allowed('dn_edit')" variant="primary" to="/dn/add">{{t('dn.operations.add')}}</WButton></div></header><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="ready?load():initialize()">{{t('dn.list.retry')}}</WButton></template></WAlert><div class="home-grid"><div class="main-column"><DashboardDaily v-if="daily" :data="daily"/><WCard v-if="!warehouse.currentWarehouse&&allowed('warehouse_read')" flush><div class="card-head"><h2>{{t('nav.warehouse')}}</h2></div><div v-for="row in warehouseRows" :key="row.warehouse.id" class="schedule-day"><WButton variant="text" @click="warehouse.selectWarehouse(row.warehouse)">{{row.warehouse.name}}</WButton><small>{{row.data?.date||'?'}} &middot; {{row.warehouse.timezone}}</small><span v-if="allowed('dn_read')">{{t('warehouse.ui.dispatch-today')}} <b>{{row.data?.dispatch_today??'?'}}</b></span><span v-if="allowed('asn_read')">{{t('warehouse.ui.receive-today')}} <b>{{row.data?.receive_today??'?'}}</b></span></div></WCard><WCard flush><div class="card-head"><h2>{{t('dashboard-design.pending')}}</h2></div><WEmptyState v-if="loading" :title="t('common.status.loading')"/><WEmptyState v-else-if="!tasks.length" :title="error?t('action-results.failed'):t('dashboard-design.empty')"/><div v-for="task in tasks.slice(0,9)" :key="task.kind+task.id" class="work-row"><i class="dot"/><div><NuxtLink class="w-work-title" :to="'/'+task.kind+'/detail/'+task.id">{{task.prefix}}-{{task.id}} <span>{{t('nav.'+task.kind)}}</span></NuxtLink><small><template v-if="taskWarehouseName(task)">{{taskWarehouseName(task)}} · </template>{{$dayjs(task.created_at,'MM/DD HH:mm',taskWarehouseId(task)||task)}}</small></div><WButton size="sm" :to="'/'+task.kind+'/detail/'+task.id">{{t('operations.ui.process')}}</WButton></div></WCard><WCard v-if="allowed('dn_read')" flush><div class="card-head"><h2>{{t('dashboard-design.outbound')}}</h2><NuxtLink class="w-home-link" to="/dn">{{t('dashboard-design.all')}} →</NuxtLink></div><div class="pipeline"><NuxtLink v-for="status in outbound" :key="status" class="w-stage" :to="{path:'/dn',query:{status}}"><small><i class="dot"/>{{t('common.status.'+status.replaceAll('_','-'))}}</small><strong>{{counts['dn-'+status]??'—'}}</strong></NuxtLink></div></WCard></div><aside><WCard v-if="allowed('asn_read')" flush><div class="card-head"><h2>{{t('dashboard-design.inbound')}}</h2><NuxtLink class="w-home-link" to="/asn">{{t('nav.ASN')}} →</NuxtLink></div><div class="pipeline"><NuxtLink v-for="status in inbound" :key="status" class="w-stage" :to="{path:'/asn',query:{status}}"><small>{{t('common.status.'+status)}}</small><strong>{{counts['asn-'+status]??'—'}}</strong></NuxtLink><NuxtLink v-if="pending&&allowed('inventory_read')" class="w-stage" to="/inventory?pending_putaway=true"><small>{{t('dashboard-design.putaway')}}</small><strong>{{pending.total_quantity}}</strong></NuxtLink><div v-else-if="pending" class="w-stage"><small>{{t('dashboard-design.putaway')}}</small><strong>{{pending.total_quantity}}</strong></div></div><NuxtLink v-for="row in receipts" :key="row.id" class="w-receipt" :to="'/asn/detail/'+row.id"><b>ASN-{{row.id}} · {{row.supplier?.name}}</b><small>{{row.warehouse?.name}} · {{t('asn.flow.summary.lines',{lines:row.detail_count,quantity:row.total_quantity})}}</small></NuxtLink></WCard><WCard v-if="allowed('inventory_read')&&(pending||low!==null||expiry)" flush><div class="card-head"><h2>{{t('dashboard-design.stock')}}</h2><NuxtLink class="w-home-link" to="/inventory">{{t('nav.inventory')}} →</NuxtLink></div><NuxtLink v-if="expiry" class="w-alert-row" to="/inventory/by-lot?status=warning"><i class="dot"/><span>{{t('expiry.warning')}}</span><strong>{{expiry.summary.warning}}</strong><small>{{t('pending-age.units')}}</small></NuxtLink><NuxtLink v-if="expiry" class="w-alert-row" to="/inventory/by-lot?status=blocked"><i class="dot"/><span>{{t('expiry.blocked')}}</span><strong>{{expiry.summary.blocked}}</strong><small>{{t('pending-age.units')}}</small></NuxtLink><NuxtLink v-if="expiry" class="w-alert-row" to="/inventory/by-lot?has_lot=false"><i class="dot"/><span>{{t('lot-rules.unassigned')}}</span><strong>{{expiry.summary.unassigned??'?'}}</strong><small>{{t('pending-age.units')}}</small></NuxtLink><NuxtLink v-if="low!==null" class="w-alert-row" to="/inventory?below_low_threshold=true"><i class="dot"/><span>{{t('dashboard-design.low')}}</span><strong>{{low}}</strong></NuxtLink><NuxtLink v-if="pending" class="w-alert-row" to="/inventory?pending_putaway=true&amp;pending_overdue_days=3"><i class="dot"/><span>{{t('dashboard-design.overdue')}}</span><strong>{{pending.overdue_quantity}}</strong></NuxtLink></WCard><WCard v-if="schedule" flush><div class="card-head"><h2>{{t('dashboard-design.schedule')}}</h2><small>{{schedule.timezone}}</small></div><WEmptyState v-if="!scheduledDays.length" :title="t('dashboard-design.empty')"/><div v-for="day in scheduledDays" :key="day.date" class="schedule-day"><strong>{{day.date}}</strong><NuxtLink v-if="day.asn" :to="{path:'/asn',query:{warehouse_todo_date:day.date}}">{{t('nav.ASN')}} <b>{{day.asn}}</b></NuxtLink><NuxtLink v-if="day.cyclecount" :to="{path:'/cyclecount',query:{status:'pending',scheduled_start_date:day.date,scheduled_end_date:day.date}}">{{t('nav.cyclecount')}} <b>{{day.cyclecount}}</b></NuxtLink><NuxtLink v-if="day.pickup" to="/delivery/pickup">{{t('nav.pickup')}} <b>{{day.pickup}}</b></NuxtLink><small v-if="!day.asn&&!day.cyclecount&&!day.pickup">{{t('dashboard-design.empty')}}</small></div></WCard></aside></div></div></template>
<style scoped>
.schedule-day{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;padding:12px 24px;border-top:1px solid var(--w-line);font-size:12px}.schedule-day>strong{width:100%;font-weight:500}.schedule-day a{color:var(--w-link);text-decoration:none}.w-work-home{overflow-wrap:anywhere;display:flex;flex-direction:column;gap:24px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}header p{font-size:12px;line-height:18px;color:var(--w-text-3);margin:0 0 4px}h1{margin:0;font-size:24px;line-height:32px;font-weight:600}.actions{display:flex;gap:8px;flex-wrap:wrap}.home-grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(300px,3fr);gap:16px;align-items:start}.main-column,aside{display:flex;flex-direction:column;gap:16px;min-width:0}.card-head{display:flex;align-items:center;gap:12px;justify-content:space-between;padding:16px 24px;border-bottom:1px solid var(--w-line)}h2{margin:0;font-size:16px;line-height:24px;font-weight:600}.w-home-link{font-size:12px;line-height:18px;color:var(--w-link);text-decoration:none;white-space:nowrap}.work-row{display:flex;align-items:center;gap:12px;padding:12px 24px;border-bottom:1px solid var(--w-line)}.work-row:last-child{border-bottom:0}.work-row>div{flex:1;min-width:0}.w-work-title{font-size:14px;line-height:22px;font-weight:500;color:var(--w-text-1);text-decoration:none}.w-work-title>span{font-weight:400;margin-left:8px;color:#9A6700}small{display:block;font-size:12px;line-height:18px;color:var(--w-text-3)}.dot{display:inline-block;flex:none;width:6px;height:6px;border-radius:50%;background:#E99B1A}.pipeline{display:flex;padding:16px 24px;gap:16px}.w-stage{flex:1;min-width:0;text-decoration:none;color:var(--w-text-1)}.w-stage+.w-stage{border-left:1px solid var(--w-line);padding-left:16px}.w-stage small{display:flex;gap:6px;align-items:center}.w-stage strong{font-size:28px;line-height:36px;font-weight:600}.w-receipt{display:block;padding:12px 24px;border-top:1px solid var(--w-line);color:var(--w-text-1);text-decoration:none}.w-receipt b{font-size:13px;line-height:20px;font-weight:500}.w-alert-row{display:flex;gap:12px;align-items:center;padding:16px 24px;text-decoration:none;color:var(--w-text-1);border-top:1px solid var(--w-line);font-size:13px;line-height:20px}.w-alert-row>span{flex:1}.w-alert-row strong{font-size:18px;font-weight:600}@media(max-width:1100px){.home-grid{grid-template-columns:minmax(0,1fr)}}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}.pipeline{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.w-stage+.w-stage{border-left:0;padding-left:0}.w-stage{min-width:80px}.work-row,.card-head,.w-receipt,.w-alert-row{padding-left:16px;padding-right:16px}}
</style>
